fun footerLength(file: File): Int = RandomAccessFile(file, "r").use { f ->
    f.seek(f.length() - 8)                                   // [length: 4 bytes LE][PAR1]
    val tail = ByteArray(8).also { f.readFully(it) }
    require(String(tail, 4, 4, Charsets.US_ASCII) == "PAR1")
    ByteBuffer.wrap(tail, 0, 4).order(ByteOrder.LITTLE_ENDIAN).int
}

fun mayContain(min: Long?, max: Long?, lo: Long, hi: Long): Boolean =
    min == null || max == null || (max >= lo && min <= hi)   // no stats: must read

fun bytesToRead(groups: List<RowGroup>, keep: List<Int>, columns: Set<String>): Long =
    groups.filter { it.index in keep }
        .sumOf { g -> columns.sumOf { g.columns.getValue(it).bytes } }
